use App\Models\Order;
use App\Models\Product;
use Illuminate\Support\Facades\DB;

// Stream large tables in batches of 500
Product::query()->where('is_active', true)->chunkById(500, function ($products) {
    foreach ($products as $product) {
        $product->update(['reviewed_at' => now()]);
    }
});

$average = Product::query()->avg('price_cents');

// Both writes commit together or not at all
DB::transaction(function () {
    $order = Order::findOrFail(42);
    $order->decrement('stock');
    $order->invoice()->create(['total_cents' => $order->total_cents]);
});

use App\Models\Category;

